import { useState, type KeyboardEvent } from 'react';
import { JxChip, JxInputField } from '@jinx-ui/react';

type ArticleTagsFieldProps = {
  label?: string;
  placeholder?: string;
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
};

export default function ArticleTagsField({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  value,
  defaultValue,
  onChange,
}: ArticleTagsFieldProps) {
  const [draft, setDraft] = useState('');
  const [error, setError] = useState<string | undefined>(undefined);
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue ?? []);

  const tags = value ?? internalTags;

  const commit = (next: string[]) => {
    if (value === undefined) setInternalTags(next);
    onChange?.(next);
  };

  const addTag = () => {
    const tag = draft.trim();
    if (tag.length === 0) return;
    if (tags.some((existing) => existing.toLowerCase() === tag.toLowerCase())) {
      setError(`Тег «${tag}» уже добавлен`);
      return;
    }
    commit([...tags, tag]);
    setDraft('');
    setError(undefined);
  };

  const removeTag = (tag: string) => {
    commit(tags.filter((existing) => existing !== tag));
    setError(undefined);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag();
      return;
    }
    if (event.key === 'Backspace' && draft.length === 0 && tags.length > 0) {
      event.preventDefault();
      removeTag(tags[tags.length - 1]);
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', fontFamily: 'var(--jx-font-sans)' }}>
      <JxInputField
        label={label}
        placeholder={placeholder}
        value={draft}
        onChange={(event) => {
          setDraft(event.target.value);
          setError(undefined);
        }}
        onKeyDown={handleKeyDown}
        onBlur={addTag}
        errorText={error}
        helperText="Enter или запятая добавляет тег, Backspace удаляет последний"
        aria-describedby="article-tags-list"
      />

      <div
        id="article-tags-list"
        role="group"
        aria-label="Выбранные теги"
        style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '8px', minHeight: '28px' }}
      >
        {tags.length === 0 ? (
          <span style={{ color: 'var(--jx-text-2)', fontSize: '13px' }}>
            Пока ни одного тега — введите первый и нажмите Enter
          </span>
        ) : (
          tags.map((tag) => (
            <JxChip
              key={tag}
              removable
              onRemove={() => removeTag(tag)}
              title={tag}
              style={{ maxWidth: '220px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}
            >
              {tag}
            </JxChip>
          ))
        )}
      </div>
    </div>
  );
}

